import sys, random, RNA, json
sys.path.insert(0, '.')

T = open('/tmp/target73.txt').read().strip()
assert len(T) == 370, len(T)
N = len(T)

# target base-pair set
def pairs_of(db):
    st=[]; pr=set()
    for i,c in enumerate(db):
        if c=='(':
            st.append(i)
        elif c==')':
            j=st.pop(); pr.add((j,i))
        elif c=='.':
            pass
        # ignore pseudoknot chars
    return pr
TP = pairs_of(T)

# map of constrained positions: a base-pair partner map
pm = [ -1 ]*N
for (i,j) in TP:
    pm[i]=j; pm[j]=i

def fold(seq):
    md = RNA.md(); md.dangles=2; md.temperature=37.0
    fc = RNA.fold_compound(seq, md)
    ss, mfe = fc.mfe()
    return ss, mfe

def pairs_of_struct(ss):
    st=[]; pr=set()
    for i,c in enumerate(ss):
        if c=='(':
            st.append(i)
        elif c==')':
            j=st.pop(); pr.add((j,i))
    return pr

def score(seq):
    ss,_ = fold(seq)
    sp = pairs_of_struct(ss)
    # reward: matched target pairs + penalty for spurious pairs + penalty for missing
    miss = len(TP - sp)
    spur = len(sp - TP)
    # also bp distance over the structure string
    return ss, miss + spur

def random_seq():
    # seed with GC-rich stems: pair positions complementary
    s = list('A'*N)
    comp = {'A':'U','U':'A','C':'G','G':'C','G'.replace('',''):'C'}
    comp = {'A':'U','U':'A','C':'G','G':'C'}
    for i in range(N):
        if pm[i] > i:
            # choose a pair
            a = random.choice(['G','C','A','U'])
            s[i]=a; s[pm[i]]=comp[a]
        elif pm[i] == -1:
            s[i]=random.choice(['A','U'])  # loops AU-rich
        else:
            pass  # already filled by partner
    return ''.join(s)

def hamish_pair_mut(seq, n_mut=2):
    s=list(seq)
    # pick a random paired position (target) and change its pair
    paired=[i for i in range(N) if pm[i]>i]
    if not paired: return seq
    for _ in range(n_mut):
        i=random.choice(paired)
        j=pm[i]
        # avoid over-GC; pick a pair type
        a=random.choice(['G','C','A','U'])
        comp={'A':'U','U':'A','C':'G','G':'C'}
        s[i]=a; s[j]=comp[a]
    # sometimes mutate a loop
    if random.random()<0.3:
        i=random.randint(0,N-1)
        if pm[i]==-1:
            s[i]=random.choice(['A','U','C','G'])
    return ''.join(s)

def anneal(seq, iters=6000, T0=2.0, Tend=0.05):
    cur=seq
    cur_ss, cur_sc = score(cur)
    best=cur; best_sc=cur_sc; best_ss=cur_ss
    for k in range(iters):
        T_ = T0 * (Tend/T0)**(k/iters)
        cand = hamish_pair_mut(cur, random.choice([1,1,2,2,3]))
        css, csc = score(cand)
        if csc < cur_sc or random.random() < pow(2.718, (cur_sc-csc)/max(T_,0.01)):
            cur=cand; cur_sc=csc; cur_ss=css
            if csc < best_sc:
                best=cand; best_sc=csc; best_ss=css
                if best_sc==0:
                    break
    return best, best_sc, best_ss

import multiprocessing as mp

def worker(seed):
    random.seed(seed)
    s0=random_seq()
    b,sc,ss=anneal(s0, iters=4000)
    return (sc, b, ss)

if __name__=='__main__':
    nproc = mp.cpu_count()
    with mp.Pool(nproc) as p:
        results = p.map(worker, range(nproc*3))
    results.sort(key=lambda x:x[0])
    best = results[0]
    print(json.dumps({'best_score':best[0], 'best_seq':best[1], 'best_ss':best[2]}))

